//! Runs one of the `binary_encoders` examples, chosen on the command line.
//!
//! TODO Reviewed ??-??-2026.

use clap::Parser;
use clap::Subcommand;

/// Demonstrates the historical Bincode 1.3.3 wire format.
mod bincode;

/// This example builds, serializes, and reads a Cap'n Proto message with code generated by `capnpc`
/// from `foo.capnp`.
mod capnp;
/// This example show how to (de)serialize CBOR data using the ciborium crate.
mod ciborium;
/// Build and read a FlatBuffer using the schema in `my_game.fbs`.
mod flatbuffers;
/// This example demonstrates how to use the `prost` crate to serialize and
mod prost;
/// Serialize and deserialize a struct with MessagePack via `rmp-serde`.
mod rmp_serde;

/// Command-line arguments.
#[derive(Parser)]
struct Cli {
    /// The example to run.
    #[command(subcommand)]
    command: Option<Commands>,
}

/// The examples that can be run.
#[derive(Subcommand)]
enum Commands {
    /// Runs the `bincode` example.
    #[command(name = "bincode")]
    Bincode,

    /// Runs the `capnp` example.
    #[command(name = "capnp")]
    Capnp,

    /// Runs the `ciborium` example.
    #[command(name = "ciborium")]
    Ciborium,

    /// Runs the `flatbuffers` example.
    #[command(name = "flatbuffers")]
    Flatbuffers,

    /// Runs the `prost` example.
    #[command(name = "prost")]
    Prost,

    /// Runs the `rmp_serde` example.
    #[command(name = "rmp_serde")]
    RmpSerde,
}

/// Runs the example selected on the command line.
fn dispatch(cli: Cli) -> anyhow::Result<()> {
    if let Some(command) = cli.command {
        match command {
            Commands::Bincode => {
                bincode::run()?;
            }
            Commands::Capnp => {
                capnp::run()?;
            }
            Commands::Ciborium => {
                ciborium::run()?;
            }
            Commands::Flatbuffers => {
                flatbuffers::run()?;
            }
            Commands::Prost => {
                prost::run()?;
            }
            Commands::RmpSerde => {
                rmp_serde::run()?;
            }
        }
    }
    Ok(())
}

/// Parses the command line and runs the selected example.
fn main() -> anyhow::Result<()> {
    dispatch(Cli::parse())
}

/// Tests behavior implemented by the surrounding module.
#[cfg(test)]
mod tests {
    use clap::CommandFactory;

    use super::*;

    /// Every example is exposed as a subcommand.
    const SUBCOMMANDS: &[&str] = &[
        "bincode",
        "capnp",
        "ciborium",
        "flatbuffers",
        "prost",
        "rmp_serde",
    ];

    /// Confirms that the command and its arguments are valid.
    #[test]
    fn test_cli_definition_is_valid() {
        Cli::command().debug_assert();
    }

    /// Each example is reachable through its own subcommand.
    #[test]
    fn test_every_subcommand_parses() {
        for name in SUBCOMMANDS {
            let cli = Cli::try_parse_from(["example", name])
                .unwrap_or_else(|e| panic!("`{name}` should parse: {e}"));
            assert!(cli.command.is_some(), "`{name}` selected no command");
        }
    }

    /// Subcommand names are unique.
    #[test]
    fn test_subcommand_names_are_unique() {
        let mut sorted = SUBCOMMANDS.to_vec();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(sorted.len(), SUBCOMMANDS.len());
    }

    /// Unknown subcommands are rejected.
    #[test]
    fn test_unknown_subcommand_is_rejected() {
        assert!(Cli::try_parse_from(["example", "no-such-example"]).is_err());
    }
}
